1	import React from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { defineMessages, useIntl } from 'react-intl';
4	import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
5	
6	const messages = defineMessages({
7	  decrement: { id: 'zimm_quantity_stepper.decrement', defaultMessage: 'Decrease quantity' },
8	  increment: { id: 'zimm_quantity_stepper.increment', defaultMessage: 'Increase quantity' },
9	});
10	
11	/** Cart-line minimum meaningful quantity. 0 would mean "remove the line", a separate action this
12	 *  molecule does not own — see ZimmQuantityStepperProps.min. */
13	const MIN_DEFAULT = 1;
14	
15	export type ZimmQuantityStepperProps = {
16	  /** Current quantity rendered between the two buttons. */
17	  quantity: number;
18	  /** Lower bound (inclusive) — decrement disables at this value. Defaults to 1. */
19	  min?: number;
20	  /**
21	   * Upper bound (inclusive) — increment disables at this value. Always required: the caller
22	   * (inventory ATS, or a hardcoded per-SKU cap — see project memory on max order quantity) is the
23	   * one that knows the real ceiling. This molecule never computes or guesses one.
24	   */
25	  max: number;
26	  /**
27	   * Fully out-of-stock / unavailable for this line — forces BOTH buttons inert regardless of
28	   * where `quantity` sits between `min`/`max`, and dims the value display to match. This molecule
29	   * does not derive availability itself (no inventory lookups here) — the caller passes the
30	   * already-resolved flag.
31	   */
32	  isUnavailable?: boolean;
33	  /** Called with the computed next quantity (`quantity - 1`) when decrement is pressed while
34	   *  active. Never called while the decrement button is inert. */
35	  onDecrement: (nextQuantity: number) => void;
36	  /** Called with the computed next quantity (`quantity + 1`) when increment is pressed while
37	   *  active. Never called while the increment button is inert. */
38	  onIncrement: (nextQuantity: number) => void;
39	};
40	
41	/**
42	 * Molecule — cart-line quantity stepper (SFCC-271). Composes two `ZimmButton variant="icon"`
43	 * controls (hover/press/focus/disabled states are entirely zimmButton.css.ts's own, unchanged
44	 * here) around a numeric value display, styled by the co-located zimmQuantityStepper.css.ts.
45	 *
46	 * Controlled, not stateful: this component never mutates `quantity` itself, it only reports the
47	 * caller's next intended value via `onDecrement`/`onIncrement` — the actual basket update (an
48	 * SFCC SDK call) belongs to whichever container wires this in, per
49	 * .claude/rules/components.md's container/presentational separation. That wiring is a later
50	 * commit in this same build and has not happened yet.
51	 *
52	 * `ariaDisabled` (not `disabled`) is used for every inert state here, matching ZimmButton's own
53	 * documented guidance for an "unavailable but explainable" control: the button stays reachable
54	 * and announced by assistive tech (its dimmed appearance and the adjacent value are the
55	 * explanation) rather than disappearing from the tab order the way a native `disabled` attribute
56	 * would. `onClick` is additionally guarded inside this component (not just left to ZimmButton's
57	 * own ariaDisabled suppression) so the "clicking does nothing" contract holds even if that
58	 * changed.
59	 *
60	 * @param props see ZimmQuantityStepperProps
61	 */
62	export const ZimmQuantityStepper = ({
63	  quantity,
64	  min = MIN_DEFAULT,
65	  max,
66	  isUnavailable = false,
67	  onDecrement,
68	  onIncrement,
69	}: ZimmQuantityStepperProps) => {
70	  const intl = useIntl();
71	  const styles = useMultiStyleConfig('ZimmQuantityStepper', { disabled: isUnavailable });
72	
73	  const decrementInert = isUnavailable || quantity <= min;
74	  const incrementInert = isUnavailable || quantity >= max;
75	
76	  const handleDecrement = () => {
77	    if (decrementInert) return;
78	    onDecrement(quantity - 1);
79	  };
80	
81	  const handleIncrement = () => {
82	    if (incrementInert) return;
83	    onIncrement(quantity + 1);
84	  };
85	
86	  return (
87	    <chakra.div __css={styles.root}>
88	      <ZimmButton
89	        variant="icon"
90	        icon="minus"
91	        label={intl.formatMessage(messages.decrement)}
92	        ariaDisabled={decrementInert}
93	        onClick={handleDecrement}
94	      />
95	      {/* aria-live: a shopper-caused change to their own just-clicked control still benefits
96	          screen reader users exploring the surrounding value, not just the button they pressed. */}
97	      <chakra.span __css={styles.value} aria-live="polite">
98	        {quantity}
99	      </chakra.span>
100	      <ZimmButton
101	        variant="icon"
102	        icon="plus"
103	        label={intl.formatMessage(messages.increment)}
104	        ariaDisabled={incrementInert}
105	        onClick={handleIncrement}
106	      />
107	    </chakra.div>
108	  );
109	};
